import { WalletHistoryDetailResponseDTO } from '~/entities/wallet/api/dtos/wallet-history-detail';
import { WalletItemDTO } from '~/entities/wallet/api/dtos/wallet-item';
import { RcppaySttusCd, TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

export const generateTitle = (item: WalletItemDTO | WalletHistoryDetailResponseDTO['tbAcnutMastr']) => {
  let itemTitle = null;
  switch (item.trnscTypeCd) {
    case TrnscTypeCd.캐시백: // 캐시백
      itemTitle = `${item.vouchNm ?? ''} ${i18n.t('cashBack')}`;
      break;
    case TrnscTypeCd.보조금: // 보조금
    case TrnscTypeCd.보조금환불: // 보조금환불
      // itemTitle = `${item.vouchNm ?? ''}`;
      itemTitle = item.walletDpstr || item.placeSecret;
      break;
    case TrnscTypeCd.캐시백환불: // 캐시백환불
      itemTitle = `${item.vouchNm ?? ''} ${i18n.t('cashbackRefund')}`;
      break;
    case TrnscTypeCd.온라인결제: // 결제
    case TrnscTypeCd.결제: // 결제
    case TrnscTypeCd.환불: // 환불
    case TrnscTypeCd.송금: // 송금
    case TrnscTypeCd.환불송금: // 송금
      itemTitle = item.walletDpstr || item.placeSecret;
      break;

    case TrnscTypeCd.전환입금: // 전환입금
      itemTitle = i18n.t('text:linkedAccountConversionDeposit');
      break;

    case TrnscTypeCd.예금전환: // 예금전환
      itemTitle = i18n.t('text:linkedAccountConversionWithdrawal');
      break;

    case TrnscTypeCd.충전: // 충전
      itemTitle =
        item.rcppaySttusCd === RcppaySttusCd.입금코드
          ? i18n.t('text:depositTokenChargeDeposit', { x: item.walletInsttNm })
          : i18n.t('text:eMoneyTokenChargeWithdrawal', { x: item.walletInsttNm });
      break;

    case TrnscTypeCd.전환: // 전환
      itemTitle =
        item.rcppaySttusCd === RcppaySttusCd.입금코드
          ? i18n.t('text:eMoneyTokenConversion', {
              x: item.walletInsttNm,
              y: item.rcppaySttusNm,
            })
          : i18n.t('text:depositTokenConversionWithdrawal', {
              x: item.walletInsttNm,
            });
      break;

    default:
      itemTitle = item.trnscMemoCn;
      break;
  }
  return itemTitle;
};
